INSERT INTO `character_knowledge` VALUES (1, 17, 1, 'white_mist_gem', 'KNOWN', '卡塔莉娜确认白雾异常与船上流转的宝石有关，并掌握继续追查宝石去向的线索。', 69);
INSERT INTO `character_profile` VALUES (1, 17, '卡塔莉娜·库莱耶思', '本作主人公，受邀登上维克尔姆号参加首次航行。', '单纯直率，喜爱美食，对危险常后知后觉。', '平安结束航行，并守护重要的人。', '同伴 > 自由 > 美食 > 安全', 'ACTIVE', '2026-09-14 22:21:51', '2026-09-14 22:21:51');
INSERT INTO `character_profile` VALUES (2, 17, '吉奥尔多·史提亚德', '金发碧眼的王子，卡塔莉娜的未婚夫。', '表面优雅，实际腹黑、占有欲强，行动果断.', '保护卡塔莉娜，并让她优先选择自己。', '卡塔莉娜 > 王室责任 > 同伴 > 体面', 'ACTIVE', '2026-09-14 22:25:35', '2026-09-14 22:25:35');
INSERT INTO `character_profile` VALUES (3, 17, '吉斯·库莱耶思', '因魔力高强而被库莱耶思家收养的义弟.', '温柔细致，责任心强，容易将担忧压在心里。', '守护卡塔莉娜，证明自己值得被家人信赖。', '卡塔莉娜 > 家人 > 责任 > 自我', 'ACTIVE', '2026-09-14 22:26:13', '2026-09-14 22:26:13');
INSERT INTO `character_profile` VALUES (4, 17, '亚兰·史提亚德', '吉奥尔多的双胞胎弟弟，拥有出众的音乐才能。', '嘴硬直接，自尊心强，情感表达笨拙。', '摆脱“王子弟弟”的比较，坦率面对自己的心意。', '自我价值 > 卡塔莉娜 > 音乐 > 王室责任', 'ACTIVE', '2026-09-14 22:26:51', '2026-09-14 22:26:51');
INSERT INTO `character_profile` VALUES (5, 17, '尼克尔·阿斯喀特', '宰相之子，外貌精致，也很疼爱妹妹索菲亚。', '沉稳克制，温和细腻，不轻易表露情绪', '守护妹妹与重要的人，并寻找真正想要的未来。', '家人 > 卡塔莉娜 > 责任 > 名望', 'ACTIVE', '2026-09-14 22:27:27', '2026-09-14 22:27:27');
INSERT INTO `character_profile` VALUES (6, 17, '罗吉·林德', '参与维克尔姆号下水典礼与首次航行的外国维修人员。', '亲切温和，擅长照顾人，隐藏着不愿轻易说出的过去', '查清航行中的异常，并保护自己认可的人。', '真相 > 同伴 > 自由 > 自我救赎', 'ACTIVE', '2026-09-14 22:28:12', '2026-09-14 22:28:12');
INSERT INTO `character_profile` VALUES (7, 17, '希尔法', '出没于白雾海域的白闇海盗团青年船长。', '神秘强势，言行带有压迫感，却有自己的原则。', '处理与海盗团及过去有关的危机，决定自己的未来。', '自由 > 船员 > 卡塔莉娜 > 过去', 'ACTIVE', '2026-09-14 22:28:52', '2026-09-14 22:28:52');
INSERT INTO `character_profile` VALUES (8, 17, '玛丽·亨特', '侯爵千金，与卡塔莉娜相识后逐渐成长为社交界闻名的淑女。', '表面端庄温柔，内心坚定，对重要的人有很强执着。', '留在卡塔莉娜身边，守护两人的关系。', '卡塔莉娜 > 自由 > 家族期待 > 社交声望', 'ACTIVE', '2026-09-15 13:56:45', '2026-09-15 13:56:45');
INSERT INTO `character_profile` VALUES (9, 17, '索菲亚·阿斯喀特', '尼克尔的妹妹，喜爱阅读，与卡塔莉娜因同读恋爱小说而成为好友。', '腼腆敏感，温柔善良，面对熟人会表现出热情。', '接纳真实的自己，与哥哥和朋友共同前进。', '家人 > 友情 > 阅读 > 自我成长', 'ACTIVE', '2026-09-15 13:57:58', '2026-09-15 13:57:58');
INSERT INTO `character_profile` VALUES (10, 17, '玛丽亚·坎贝尔', '原本乙女游戏《FORTUNE LOVER》的主人公，擅长制作点心。', '勤奋温和，乐于帮助他人，心意坚定。', '以自己的能力帮助身边的人，走向想要的未来。', '同伴 > 努力 > 善意 > 自我实现', 'ACTIVE', '2026-09-15 13:58:47', '2026-09-15 13:58:47');
INSERT INTO `character_relation` VALUES (1, 17, 1, 2, 'TRUST', '航海危机中仍愿意相信吉奥尔多的判断。');
INSERT INTO `character_relation` VALUES (2, 17, 1, 3, 'TRUST', '对义弟的担忧与照顾抱有信任');
INSERT INTO `character_relation` VALUES (3, 17, 1, 4, 'ADMIRE', '认可亚兰的音乐才能与努力');
INSERT INTO `character_relation` VALUES (4, 17, 2, 1, 'PROTECT', '将保护未婚妻视为优先事项');
INSERT INTO `character_relation` VALUES (5, 17, 1, 5, 'TRUST', '在危机中信赖尼克尔冷静的判断。');
INSERT INTO `character_relation` VALUES (6, 17, 1, 6, 'COOPERATE', '围绕维克尔姆号异常共同调查');
INSERT INTO `character_relation` VALUES (7, 17, 1, 7, 'CONFLICT', '对白闇海盗团与白雾海域的立场存在冲突。');
INSERT INTO `character_relation` VALUES (8, 17, 2, 4, 'TWIN', '双胞胎王子，既亲近也常彼此较劲');
INSERT INTO `character_relation` VALUES (9, 17, 4, 2, 'RIVAL', '长期处在兄长光环下，想证明自身价值。');
INSERT INTO `character_relation` VALUES (10, 17, 3, 1, 'FAMILY', '被库莱耶思家收养后，与卡塔莉娜成为家人。');
INSERT INTO `character_relation` VALUES (11, 17, 5, 9, 'PROTECT', '疼爱并保护妹妹。');
INSERT INTO `character_relation` VALUES (12, 17, 1, 9, 'FRIEND', '因共同兴趣而成为亲近的朋友.');
INSERT INTO `character_relation` VALUES (13, 17, 1, 10, 'FRIEND', '在校园与航海事件中相互信赖。');
INSERT INTO `character_relation` VALUES (14, 17, 1, 8, 'FRIEND', '重要友人，关系在部分分支中会发生强烈变化.');
INSERT INTO `character_relation` VALUES (15, 17, 8, 1, 'DEVOTION', '对卡塔莉娜抱有极强的执着。');
INSERT INTO `character_relation` VALUES (16, 17, 9, 5, 'SIBLING', '依赖并珍视兄长。');
INSERT INTO `character_relation` VALUES (17, 17, 6, 7, 'ALLY', '航海危机中存在需要协商与合作的立场。');
