INSERT INTO `story_node` VALUES (36, 17, 'deck_start', '航程第七日', '受邀参加航行的第七日，海面升起异常白雾。你必须决定先调查船上异状，还是相信某位同行者。', 'NORMAL', '客轮甲板', 1, -153.58, 347.96, '2026-09-14 20:25:17', '2026-09-14 20:36:37');
INSERT INTO `story_node` VALUES (38, 17, 'route_hub', '雾中分岔', '白雾吞没航线。你可以选择调查不同方向的异状；部分航线需要满足条件后才会出现。', 'NORMAL', '观景甲板', 0, 175.16, 345.75, '2026-09-14 20:27:43', '2026-09-14 20:36:40');
INSERT INTO `story_node` VALUES (39, 17, 'route_geordo', '吉奥多航线', '与吉奥多共同调查船舱异状。用于测试第一条主路线', 'NORMAL', '船舱走廊', 0, 476.87, 140.00, '2026-09-14 20:35:01', '2026-09-14 20:52:53');
INSERT INTO `story_node` VALUES (40, 17, 'g_ch4_confinement', '吉奥多线 CHAPTER 4：封闭与险境', '调查受到阻碍，船内危险持续逼近。此节点用于测试风险累计、线索条件和下一章节分支。', 'NORMAL', '封锁的船舱', 0, 781.12, 58.09, '2026-09-14 20:54:24', '2026-09-14 21:33:44');
INSERT INTO `story_node` VALUES (41, 17, 'g_ch5_mistake', '吉奥多线 CHAPTER 5：说错的话', '误会加深，必须决定坦白掌握的线索，或继续隐瞒。用于测试同一节点的多选项分歧。', 'NORMAL', '船舱会客室', 0, 1079.19, -60.37, '2026-09-14 21:18:39', '2026-09-14 21:34:42');
INSERT INTO `story_node` VALUES (42, 17, 'g_ch6_escape_plan', '吉奥多线 CHAPTER 6：探索与逃脱计划', '你们整理线索并制定逃脱计划。用于测试多项效果连续执行。', 'NORMAL', '航海图室', 0, 1328.63, -183.41, '2026-09-14 21:19:17', '2026-09-14 21:35:48');
INSERT INTO `story_node` VALUES (43, 17, 'g_ch7_important', '吉奥多线 CHAPTER 7：因为你很重要', '真相即将揭开，最终选择将由线索、风险和关系状态共同决定。', 'NORMAL', '黎明甲板', 0, 1608.05, -171.56, '2026-09-14 21:20:25', '2026-09-14 21:36:18');
INSERT INTO `story_node` VALUES (44, 17, 'g_another_captive', '吉奥多线 ANOTHER ENDING：被吉奥多囚禁', '错误判断导致行动受限。本结局用于测试中途分支结局与回放。', 'ENDING', '隐蔽船舱', 0, 777.41, 241.45, '2026-09-14 21:21:40', '2026-09-14 21:29:23');
INSERT INTO `story_node` VALUES (45, 17, 'g_bad_stab', '吉奥多线 毁灭 BAD ENDING', '风险失控，调查失败。本结局用于验证坏结局路径和问题反馈。', 'ENDING', '暴风甲板', 0, 1384.43, 185.85, '2026-09-14 21:22:28', '2026-09-14 21:35:22');
INSERT INTO `story_node` VALUES (46, 17, 'g_good_lovers', '吉奥多线 GOOD ENDING', '你们化解危机，但仍有未解开的心意。本结局用于验证条件达成后的普通成功结局。', 'ENDING', '港口', 0, 1906.22, -336.08, '2026-09-14 21:23:24', '2026-09-14 21:36:15');
INSERT INTO `story_node` VALUES (47, 17, 'g_happy_special', '吉奥多线 HAPPY ENDING', '线索、信任与关键物品都已满足，航程迎来圆满收束。本结局用于验证复合条件。', 'ENDING', '重获平静的甲板', 0, 1910.26, -58.65, '2026-09-14 21:23:53', '2026-09-14 21:36:33');
INSERT INTO `story_node` VALUES (48, 17, 'k_ch3_regret', '吉斯线 CHAPTER 3：对弱小的悔恨', '白雾封锁了海面，船上的异常也愈发明显。吉斯得知有人在混乱中受伤后，将责任揽到自己身上：如果他能更早察觉危险，也许就不会让任何人陷入恐惧。卡塔莉娜没有责怪他，而是提议两人先确认失踪船员最后出现的位置。吉斯压下自责，决定用行动弥补自己的迟疑', 'NORMAL', '下层船舱', 0, 478.13, 443.25, '2026-09-15 14:31:57', '2026-09-15 14:34:45');
INSERT INTO `story_node` VALUES (49, 17, 'k_ch4_restless', '吉斯线 CHAPTER 4：焦躁在心头翻腾', '甲板上能见度越来越低，远处不时传来不属于维克尔姆号的声响。吉斯判断船体可能正在被暗流推向危险海域，但贸然下船同样可能造成更大的伤亡。面对风暴与未知威胁，他第一次无法立刻给出正确答案。卡塔莉娜看出他的焦躁，提醒他先相信已经掌握的线索。', 'NORMAL', '雾中甲板', 0, 785.57, 438.65, '2026-09-15 14:32:32', '2026-09-15 21:56:28');
INSERT INTO `story_node` VALUES (50, 17, 'k_bad_drown', '吉斯线 BAD ENDING：葬身大海', '焦急让判断失去平衡。众人选择在风暴中强行离开船只，却低估了白雾海域的暗流。救援方向被海浪吞没，原本能共同面对的危机变成无法挽回的灾难。吉斯只能在翻涌的海面上呼喊卡塔莉娜的名字，航行就此终结。', 'ENDING', '暴风海面', 0, 996.86, 391.53, '2026-09-15 14:33:23', '2026-09-15 14:39:16');
INSERT INTO `story_node` VALUES (51, 17, 'k_ch5_recover', '吉斯线 CHAPTER 5：好转的第一步', '留在船上的决定带来了新的转机。卡塔莉娜从受损的航海记录中发现，异常并非随机发生，而是有人刻意利用船内的恐慌掩盖行动。吉斯重新整理线索，将船员分为搜查、救援和守备三组。看到局面逐渐稳定，他终于意识到，承担责任并不意味着独自背负一切。', 'NORMAL', '临时医务室', 0, 1005.13, 559.79, '2026-09-15 14:35:35', '2026-09-15 14:40:53');
INSERT INTO `story_node` VALUES (52, 17, 'k_ch6_shadow', '吉斯线 CHAPTER 6：溜走的身影', '夜色降临后，一个可疑身影从货舱深处掠过。吉斯与卡塔莉娜循着被移动过的货物追查，发现有人一直在寻找与白雾有关的旧航图。吉斯担心这是专为卡塔莉娜设下的诱饵，却又不愿放弃唯一的突破口。两人约定彼此照应，继续深入调查。', 'NORMAL', '货舱通道', 0, 1248.45, 557.90, '2026-09-15 14:36:10', '2026-09-15 14:57:52');
INSERT INTO `story_node` VALUES (53, 17, 'k_ch7_feelings', '吉斯线 CHAPTER 7：面对那份情感', '航图揭示了脱离白雾的路线，也让危机迎来最后关头。吉斯终于承认，令他害怕的并非危险本身，而是可能失去卡塔莉娜。他不再以“家人应尽的责任”掩饰关心，而是坦率说明自己的心意。卡塔莉娜必须决定：是把这份感情留在未说完的话里，还是回应他的期待。', 'NORMAL', '船首', 0, 1500.34, 556.02, '2026-09-15 14:36:55', '2026-09-15 14:42:09');
INSERT INTO `story_node` VALUES (54, 17, 'k_bad_murder', '吉斯线 BAD ENDING：如路人角色般遭到杀害', '在胜利似乎近在眼前时，卡塔莉娜轻信了陌生人的指引，独自走入被布置好的暗室。吉斯赶到时已来不及阻止陷阱启动。线索被夺走，危机也没有真正结束；两人原本能够共同抵达的未来，被一次疏忽彻底切断。', 'ENDING', '船舱暗室', 0, 1772.47, 322.12, '2026-09-15 14:37:27', '2026-09-15 14:41:42');
INSERT INTO `story_node` VALUES (55, 17, 'k_good_memory', '吉斯线 GOOD ENDING：想要铭记的瞬间', '维克尔姆号终于驶出白雾，所有人平安归航。吉斯没有急着追问答案，只是陪卡塔莉娜走过安静的码头。他们约定把这段共同战胜恐惧的经历好好记住，也将尚未说出口的感情留给未来慢慢确认。危机结束了，但两人的关系已不再和从前一样。', 'ENDING', '靠岸码头', 0, 1749.51, 523.65, '2026-09-15 14:38:06', '2026-09-15 14:41:35');
INSERT INTO `story_node` VALUES (56, 17, 'k_happy_promise', '吉斯线 HAPPY ENDING：恋人间的约定', '真相大白后，吉斯终于放下始终压在心里的不安。他向卡塔莉娜坦白，自己想守护她，并非只是出于家人的责任。卡塔莉娜回应了这份真心。黄昏的港口见证了两人的约定：无论下一次航行通往哪里，他们都会以恋人的身份并肩前行。', 'ENDING', '港口黄昏', 0, 1744.41, 735.09, '2026-09-15 14:38:54', '2026-09-15 14:41:36');
INSERT INTO `story_node` VALUES (57, 17, 'a_ch3_escape', '亚兰线 CHAPTER 3：船上的逃走行动', '白雾压向维克尔姆号，船上的通道陆续被封锁。亚兰判断继续等待只会失去主动权，于是提出从下层甲板绕开危险区域的逃离方案。表面上他语气强硬，实际却不断确认卡塔莉娜是否跟得上。两人在狭窄的船舱中前进，也逐渐发现这场异常并不是单纯的海难。', 'NORMAL', '下层甲板', 0, 475.64, 777.95, '2026-09-15 14:44:24', '2026-09-15 21:05:30');
INSERT INTO `story_node` VALUES (58, 17, 'a_ch4_fog_truth', '亚兰线 CHAPTER 4：隐藏在雾中的真正用意', '亚兰在遗留的设备和异常航线中找到共同点：白雾并非自然形成，而是有人刻意利用它制造混乱。他不愿再被动地接受安排，决定找出操纵者的目标。卡塔莉娜则从零碎情报中察觉，敌人想要的可能不只是维克尔姆号本身。', 'NORMAL', '白雾海域', 0, 711.58, 749.30, '2026-09-15 14:45:17', '2026-09-15 21:05:27');
INSERT INTO `story_node` VALUES (59, 17, 'a_ch5_distance', '亚兰线 CHAPTER 5：两人的距离', '短暂脱离追踪后，亚兰和卡塔莉娜在船尾获得喘息的机会。亚兰坦言自己总觉得无法追上吉奥尔多，也不擅长把真正的情绪说出口。卡塔莉娜告诉他，自己看到的从来不是某个人的影子，而是一直努力前进的亚兰。这句话让两人之间原本遥远的距离开始缩短。', 'NORMAL', '船尾平台', 0, 978.28, 764.72, '2026-09-15 14:46:00', '2026-09-15 21:05:26');
INSERT INTO `story_node` VALUES (60, 17, 'a_ch6_confession', '亚兰线 CHAPTER 6：罪恶的告解', '调查逼近核心时，一名关键人物提出了迟来的坦白。亚兰必须判断这份告解是为了赎罪，还是为了拖延时间。面对过去造成的伤害，他没有立刻原谅对方，而是选择带着卡塔莉娜继续寻找能够证明真相的证据。真正的勇气，不是忘记伤痛，而是带着伤痛作出正确选择。', 'NORMAL', '船长室外', 0, 1221.62, 752.05, '2026-09-15 14:47:37', '2026-09-15 21:05:25');
INSERT INTO `story_node` VALUES (61, 17, 'a_ch7_sincerity', '亚兰线 CHAPTER 7：率直的心意', '破雾的航线已经找到，但敌人仍试图阻止维克尔姆号离开。亚兰带领众人完成最后的反击，也终于不再用逞强掩饰担忧。他向卡塔莉娜承认，自己想被她看见、被她选择。卡塔莉娜必须决定如何回应这份率直而笨拙的心意。', 'NORMAL', '黎明甲板', 0, 1968.39, 913.17, '2026-09-15 14:48:21', '2026-09-16 20:49:32');
INSERT INTO `story_node` VALUES (62, 17, 'a_bad_sword', '亚兰线 BAD ENDING：遭人用剑砍杀', '在最后的交战中，亚兰为了保护卡塔莉娜而忽视了侧面的威胁。敌人的剑刃划破了本应结束的黎明，逃离白雾的计划也被迫中断。未能彼此信任的选择，让所有努力停在最接近成功的一刻。', 'ENDING', '交战甲板', 0, 2237.73, 728.89, '2026-09-15 14:49:12', '2026-09-15 21:04:38');
INSERT INTO `story_node` VALUES (63, 17, 'a_good_lunch', '亚兰线 GOOD ENDING：秘密的午餐时光', '风波结束后，亚兰邀请卡塔莉娜共进一顿不对外公开的午餐。没有王子的身份，也没有船上的危机，两人终于能以平等而轻松的方式交谈。亚兰没有急着要求答案，只希望这段只属于彼此的时光能再长一点。', 'ENDING', '靠岸后的餐厅', 0, 2271.12, 1026.79, '2026-09-15 14:49:49', '2026-09-15 21:04:39');
INSERT INTO `story_node` VALUES (64, 17, 'a_happy_words', '亚兰线 HAPPY ENDING：想要传达的重要话语', '回到王都后，亚兰在熟悉的花园里向卡塔莉娜说出了始终没有说出口的话。他不再把自己与任何人比较，也不再害怕自己的感情会被拒绝。卡塔莉娜回应了他的真心，两人决定共同面对之后的日子。', 'ENDING', '王都花园', 0, 2274.73, 1209.54, '2026-09-15 14:50:34', '2026-09-15 21:04:41');
INSERT INTO `story_node` VALUES (65, 17, 'a_another_mary', '亚兰线 ANOTHER ENDING：被玛丽掳走', '卡塔莉娜在混乱中被玛丽带离维克尔姆号，亚兰的追查被迫中止。玛丽坚信只有远离所有航线与危机，卡塔莉娜才能安全。故事因此偏离原本的归航计划，走向一条意外而封闭的分支。', 'ENDING', '港口仓库', 0, 2273.97, 1410.28, '2026-09-15 14:51:06', '2026-09-15 21:04:44');
INSERT INTO `story_node` VALUES (66, 17, 'n_ch3_chaos', '尼克尔线 CHAPTER 3：混沌之夜', '白雾笼罩海面后，维克尔姆号上的灯火接连熄灭，船员也因不明声响陷入混乱。尼克尔没有急于追逐可疑目标，而是先安排众人撤离危险区域。卡塔莉娜从他冷静的指挥中得到安心，两人决定先找出异常最早出现的地点。', 'NORMAL', '夜间船舱', 0, 381.49, 1293.30, '2026-09-15 15:18:28', '2026-09-15 21:05:16');
INSERT INTO `story_node` VALUES (67, 17, 'n_ch4_crossed', '尼克尔线 CHAPTER 4：交错的情感', '线索指向被遗弃的观景甲板。尼克尔发现有人利用船上乘客之间的不安制造误会，而他自己也无法再把对卡塔莉娜的关心单纯视作朋友之间的照顾。面对交错的情感与不断逼近的危机，他必须作出选择。', 'NORMAL', '观景甲板', 0, 618.61, 1287.88, '2026-09-15 15:19:04', '2026-09-15 21:05:13');
INSERT INTO `story_node` VALUES (68, 17, 'n_bad_round', '尼克尔线 BAD ENDING：变得圆滚滚的', '卡塔莉娜误将储藏室里的异常物资当成安全补给，导致身体出现无法控制的变化。混乱让原本的调查计划彻底失效，尼克尔虽然尽力处理后果，却无法阻止危机进一步蔓延。', 'ENDING', '异常储藏室', 0, 1121.45, 1067.05, '2026-09-15 15:19:46', '2026-09-15 21:05:09');
INSERT INTO `story_node` VALUES (69, 17, 'n_ch5_turning', '尼克尔线 CHAPTER 5：突如其来的转机', '在几乎无计可施时，卡塔莉娜从旧航海记录中找到一段被刻意划去的记载。尼克尔据此判断，白雾与一颗在船上流转的宝石有关。原本停滞的调查出现突破，两人决定沿着记录中的方位继续追查。', 'NORMAL', '船舱资料室', 0, 925.92, 1274.13, '2026-09-15 15:20:09', '2026-09-15 21:05:11');
INSERT INTO `story_node` VALUES (70, 17, 'n_ch6_suspicion', '尼克尔线 CHAPTER 6：可疑的气息', '越接近真相，空气中越弥漫着不自然的气息。尼克尔察觉敌人正在诱导他们踏入白雾深处，也担心卡塔莉娜会因好奇而陷入危险。两人找到关键证据，却必须决定是冒险深入，还是先回船重整计划。', 'NORMAL', '白雾边缘', 0, 1317.78, 1279.94, '2026-09-15 15:20:29', '2026-09-15 21:05:06');
INSERT INTO `story_node` VALUES (71, 17, 'n_ch7_gem', '尼克尔线 CHAPTER 7：倾注心意的宝石与奇迹', '宝石的力量终于被正确理解，白雾也开始消散。尼克尔借此看清一直被自己克制的感情：他不只想保护卡塔莉娜，更希望成为她可以依赖的人。在最后的抉择前，两人必须以信任和勇气结束这场危机。', 'NORMAL', '雾海遗迹', 0, 1645.03, 1284.59, '2026-09-15 15:21:06', '2026-09-15 21:05:05');
INSERT INTO `story_node` VALUES (72, 17, 'n_bad_disappear', '尼克尔线 BAD ENDING：「我」消失了', '卡塔莉娜独自追随可疑气息进入白雾，等尼克尔赶到时，只剩下逐渐消散的痕迹。宝石失去控制，维克尔姆号也再度被浓雾吞没。尼克尔没能守住最重要的人，故事在无声的海面上结束。', 'ENDING', '白雾深处', 0, 1576.17, 1037.48, '2026-09-15 15:21:35', '2026-09-15 21:05:08');
INSERT INTO `story_node` VALUES (73, 17, 'n_good_plan', '尼克尔线 GOOD ENDING：令人雀跃的未来规划', '平安归航后，尼克尔与卡塔莉娜在书房整理航行记录。经历这次事件，两人都意识到未来不应只由责任决定。尼克尔提出与她共同规划下一段旅程，关系虽然尚未说破，却已朝着更明亮的方向前进。', 'ENDING', '王都书房', 0, 1989.82, 1149.26, '2026-09-15 15:22:19', '2026-09-15 21:05:02');
INSERT INTO `story_node` VALUES (74, 17, 'n_happy_rose', '尼克尔线 HAPPY ENDING：幸福的玫瑰与密会', '危机过去后，尼克尔邀请卡塔莉娜来到安静的玫瑰庭园。宝石带来的阴影已经消散，留下的是两人共同守护彼此的记忆。尼克尔终于坦率表达心意，卡塔莉娜也回应了他的期待，密会成为幸福新篇章的开端。', 'ENDING', '玫瑰庭园', 0, 1966.03, 1490.58, '2026-09-15 15:22:49', '2026-09-15 21:05:03');
INSERT INTO `story_node` VALUES (75, 17, 'r_ch3_tenderness', 'CHAPTER 3：半梦半醒间的温柔', '连日的雾海使卡塔莉娜疲惫不堪。她在休息舱醒来时，发现罗吉守在门外，还留下一杯温热的饮品。罗吉依旧用轻松的语气掩饰自己的关心，却避开了有关船上骚动的提问。卡塔莉娜察觉到他似乎知道更多，于是决定顺着这份看似温柔的照顾，找出他隐瞒的真相。', 'NORMAL', '夜间休息舱', 0, 355.00, 1627.19, '2026-09-15 21:09:27', '2026-09-15 21:24:04');
INSERT INTO `story_node` VALUES (76, 17, 'r_bad_explosion', 'BAD ENDING：船爆炸了', '卡塔莉娜轻信罗吉留下的错误路线，独自前往船尾。那里堆放的危险物资已经被人动过手脚，火花点燃了火药。爆炸吞没甲板，原本能够避免的危机最终化为一场无法挽回的事故。', 'ENDING', '船尾火药库', 0, 624.81, 1460.80, '2026-09-15 21:09:55', '2026-09-15 21:24:01');
INSERT INTO `story_node` VALUES (77, 17, 'r_ch4_detained', 'CHAPTER 4：舒适的软禁工作！？', '罗吉以“外面不安全”为由，将卡塔莉娜安置在舒适得过分的贵宾舱中。书籍、点心与服务一应俱全，唯独房门被悄悄锁上。卡塔莉娜没有立刻拆穿他，而是在谈话中发现罗吉并非单纯的敌人；他似乎正被某个更危险的势力逼迫行动。', 'NORMAL', '被封锁的贵宾舱', 0, 627.61, 1678.28, '2026-09-15 21:10:37', '2026-09-15 21:26:01');
INSERT INTO `story_node` VALUES (78, 17, 'r_ch5_truth', 'CHAPTER 5：罗吉的真相', '卡塔莉娜从罗吉遗漏的航线记录中，找到一封未寄出的信。信中提到一项针对乘客的交易，以及罗吉不得不承担的条件。面对证据，罗吉终于承认自己接近她并非偶然，但也坦白自己已经不愿继续伤害她。两人必须决定是否共同面对幕后主使。', 'NORMAL', '秘密航线室', 0, 872.21, 1677.33, '2026-09-15 21:12:17', '2026-09-15 21:26:00');
INSERT INTO `story_node` VALUES (79, 17, 'r_bad_cliff', 'BAD ENDING：摔下悬崖', '卡塔莉娜没有等待罗吉说明计划，便独自前往交易地点。浓雾遮住了悬崖边缘，也遮住了敌人的陷阱。罗吉赶到时只看见坠落的痕迹，所有没能说出口的话都被海浪吞没。', 'ENDING', '海蚀悬崖', 0, 1127.25, 1539.70, '2026-09-15 21:13:06', '2026-09-15 21:26:41');
INSERT INTO `story_node` VALUES (80, 17, 'r_ch6_request', 'CHAPTER 6：要求协助', '罗吉提出请求，希望卡塔莉娜协助他截获交易名单。他不再用玩笑转移话题，而是第一次认真说明自己的恐惧：他担心自己一旦反抗，就会连累她。卡塔莉娜从名单中找到能够推翻幕后主使的证据，也让罗吉明白，他不必独自承担一切。', 'NORMAL', '隐秘码头', 0, 1155.83, 1735.53, '2026-09-15 21:14:45', '2026-09-15 21:29:37');
INSERT INTO `story_node` VALUES (81, 17, 'r_ch7_honesty', 'CHAPTER 7：毫无虚假的心意', '交易被阻止后，罗吉站在晨雾渐散的甲板上，将过去的谎言与真正的想法全部告诉卡塔莉娜。他承认最初确实抱着目的接近她，却也承认后来每一次保护都出自真心。面对终于不再逃避的罗吉，卡塔莉娜决定如何回应这份迟来的坦诚。', 'NORMAL', '黎明前的甲板', 0, 1384.24, 1741.63, '2026-09-15 21:16:37', '2026-09-15 21:29:36');
INSERT INTO `story_node` VALUES (82, 17, 'r_good_reunion', 'GOOD ENDING：重逢的约定', '事件告一段落后，罗吉必须先去处理过去留下的问题。他没有要求卡塔莉娜立刻给出答案，只与她约定，等一切真正结束后，会以不带谎言的身份再次相见。卡塔莉娜目送船只离港，也开始期待那场重逢。', 'ENDING', '离港码头', 0, 1758.80, 1606.84, '2026-09-15 21:17:19', '2026-09-15 21:44:54');
INSERT INTO `story_node` VALUES (83, 17, 'r_happy_hand', 'HAPPY ENDING：牵着心爱之人的手', '罗吉完成了对过去的清算，带着不再需要隐藏的身份回到港口。他主动伸出手，坦率说出希望今后每段航程都能与卡塔莉娜同行。卡塔莉娜握住他的手，两人在阳光下踏上新的旅程。', 'ENDING', '阳光下的港口', 0, 1812.53, 1817.67, '2026-09-15 21:17:41', '2026-09-15 21:44:52');
INSERT INTO `story_node` VALUES (84, 17, 's_ch3_truth', 'CHAPTER 3：邂逅的真相', '卡塔莉娜在浓雾中与希尔法再次相遇。对方似乎早已知道她会经过这里，也知道船上隐藏的危险。希尔法没有解释自己的来历，只提醒她不要轻信任何海盗的承诺。卡塔莉娜决定跟随他的线索，确认这场邂逅究竟是偶然还是被人安排。', 'NORMAL', '雾海中的小艇', 0, 360.73, 1870.81, '2026-09-15 21:34:02', '2026-09-15 21:34:06');
INSERT INTO `story_node` VALUES (85, 17, 's_ch4_pirate', 'CHAPTER 4：泯灭人性的海盗', '希尔法带卡塔莉娜进入一处被废弃的海盗据点。这里留下的记录显示，有人正利用白雾和恐惧控制航线。希尔法对那些残酷交易表现出异常强烈的厌恶，却也因此暴露出自己与海盗势力之间并不简单的过去。', 'NORMAL', '海盗据点', 0, 606.29, 1882.18, '2026-09-15 21:34:23', '2026-09-15 21:42:37');
INSERT INTO `story_node` VALUES (86, 17, 's_another_farmer', 'ANOTHER ENDING：变成农夫', '卡塔莉娜为了逃离危险，接受了“从此不再过问海上事务”的提议。她和希尔法离开航线，在偏远农庄过上平静生活。危机暂时远去，但真相也永远被留在海雾之中。', 'ENDING', '远离海洋的农庄', 0, 866.01, 1837.41, '2026-09-15 21:34:49', '2026-09-15 21:42:13');
INSERT INTO `story_node` VALUES (87, 17, 's_ch5_intent', 'CHAPTER 5：浮现的企图', '卡塔莉娜与希尔法在地下仓库发现了运输名单。名单上的名字与白雾事件、宝石交易和失踪的船员全部有关。希尔法终于承认，自己曾被迫参与其中，如今却想亲手终结这场阴谋。卡塔莉娜决定帮助他夺回主动权.', 'NORMAL', '地下仓库', 0, 865.68, 2016.54, '2026-09-15 21:35:11', '2026-09-15 21:42:33');
INSERT INTO `story_node` VALUES (88, 17, 's_ch6_darkness', 'CHAPTER 6：心中蠢动的黑暗', '暴风雨让船只偏离航线，幕后之人试图逼希尔法重回过去的身份。卡塔莉娜发现一份能证明希尔法被胁迫的记录，也明白他真正害怕的不是敌人，而是再次成为伤害他人的人。她必须选择是否继续相信他。', 'NORMAL', '暴风雨中的船桥', 0, 1137.59, 2023.86, '2026-09-15 21:36:32', '2026-09-15 21:43:14');
INSERT INTO `story_node` VALUES (89, 17, 's_ch7_farewell', 'CHAPTER 7：挥别过去', '真相公开后，希尔法终于有机会切断与旧势力的联系。他站在风暴后的甲板上，准备独自离开，认为自己没有资格继续留在卡塔莉娜身边。卡塔莉娜却告诉他，摆脱过去并不意味着必须独自承担未来', 'NORMAL', '风暴后的甲板', 0, 1348.64, 2019.50, '2026-09-15 21:37:16', '2026-09-15 21:45:54');
INSERT INTO `story_node` VALUES (90, 17, 's_bad_betrayal', 'BAD ENDING：遭到背刺', '卡塔莉娜轻信了敌人假意提出的和解，在交出证据时遭到背叛。希尔法虽及时赶到，却无法扭转已经失控的局面。被隐藏的阴谋再次得逞，故事在冰冷的背叛中结束。', 'ENDING', '交易地点', 0, 1603.56, 1905.09, '2026-09-15 21:37:41', '2026-09-15 21:44:55');
INSERT INTO `story_node` VALUES (91, 17, 's_good_voyage', 'GOOD ENDING：迈向两人冒险的航行', '事件结束后，希尔法没有立刻许下浪漫承诺，而是邀请卡塔莉娜一同踏上新的航程。他们仍有许多未知的海域要面对，但已经决定以平等的伙伴身份前进。属于两人的冒险，在新的海图上展开。', 'ENDING', '新的航船', 0, 1621.75, 2074.57, '2026-09-15 21:38:29', '2026-09-15 21:44:57');
INSERT INTO `story_node` VALUES (92, 17, 's_happy_fiancee', 'HAPPY ENDING：坏人婚约对象', '希尔法在众人面前承认自己曾经是“坏人”，也坦率说出今后希望承担的责任。他把象征新航程的信物交给卡塔莉娜，正式请求与她订下未来。卡塔莉娜笑着接受，这位曾被过去束缚的海盗终于拥有了值得守护的幸福。', 'ENDING', '港口庆典', 0, 1613.72, 2260.34, '2026-09-15 21:39:01', '2026-09-15 21:44:58');
INSERT INTO `story_node` VALUES (96, 17, 'test_variable_ref', '测试-变量引用', '用于测试状态变量引用保护', 'NORMAL', NULL, 0, 1985.71, 2045.06, '2026-09-17 14:55:47', '2026-09-17 14:56:48');
INSERT INTO `story_node` VALUES (97, 17, '1111', '1111', '11111', 'NORMAL', NULL, 0, 2244.17, 2037.50, '2026-09-17 14:56:45', '2026-09-17 14:56:47');
