t\": \"冒险穿越危险区域\", \"sourceNodeId\": 40, \"targetNodeId\": 45}, {\"id\": 31, \"enabled\": true, \"createdAt\": \"2026-09-14T21:35:18\", \"projectId\": 17, \"sortOrder\": 1, \"updatedAt\": \"2026-09-14T21:35:18\", \"choiceText\": \"隐瞒真相，单独行动\", \"sourceNodeId\": 41, \"targetNodeId\": 45}, {\"id\": 34, \"enabled\": true, \"createdAt\": \"2026-09-14T21:36:43\", \"projectId\": 17, \"sortOrder\": 1, \"updatedAt\": \"2026-09-14T21:36:43\", \"choiceText\": \"相信彼此，完成最终计划\", \"sourceNodeId\": 43, \"targetNodeId\": 47}], \"effects\": [{\"id\": 11, \"choiceId\": 24, \"operation\": \"ADD\", \"sortOrder\": 0, \"variableId\": 14, \"operandValue\": \"1\"}, {\"id\": 12, \"choiceId\": 24, \"operation\": \"ADD\", \"sortOrder\": 1, \"variableId\": 15, \"operandValue\": \"1\"}, {\"id\": 13, \"choiceId\": 25, \"operation\": \"ADD\", \"sortOrder\": 0, \"variableId\": 18, \"operandValue\": \"1\"}, {\"id\": 14, \"choiceId\": 25, \"operation\": \"ADD\", \"sortOrder\": 1, \"variableId\": 17, \"operandValue\": \"1\"}, {\"id\": 15, \"choiceId\": 30, \"operation\": \"ADD\", \"sortOrder\": 0, \"variableId\": 15, \"operandValue\": \"1\"}, {\"id\": 16, \"choiceId\": 30, \"operation\": \"ADD\", \"sortOrder\": 1, \"variableId\": 18, \"operandValue\": \"1\"}, {\"id\": 17, \"choiceId\": 32, \"operation\": \"SET\", \"sortOrder\": 0, \"variableId\": 16, \"operandValue\": \"true\"}, {\"id\": 18, \"choiceId\": 32, \"operation\": \"ADD\", \"sortOrder\": 1, \"variableId\": 14, \"operandValue\": \"1\"}], \"project\": {\"id\": 17, \"name\": \"六线航海乙女游戏测试\", \"status\": \"ACTIVE\", \"ownerId\": 3, \"createdAt\": \"2026-09-14T20:16:50\", \"updatedAt\": \"2026-09-14T20:16:50\", \"description\": \"仅用于课程内部验收：验证六角色路线、条件解锁、多结局、回放和问题检测。\"}, \"knowledge\": [], \"relations\": [], \"variables\": [{\"id\": 14, \"projectId\": 17, \"valueType\": \"INTEGER\", \"description\": \"控制六条路线与隐藏路线的解锁进度\", \"displayName\": \"路线推进度\", \"variableKey\": \"route_progress\", \"initialValue\": \"0\"}, {\"id\": 15, \"projectId\": 17, \"valu