tNodeId\": 72}, {\"id\": 60, \"enabled\": true, \"createdAt\": \"2026-09-15T20:57:13\", \"projectId\": 17, \"sortOrder\": 0, \"updatedAt\": \"2026-09-15T20:57:13\", \"choiceText\": \"将这份心意交给未来慢慢确认\", \"sourceNodeId\": 71, \"targetNodeId\": 73}, {\"id\": 63, \"enabled\": true, \"createdAt\": \"2026-09-15T21:24:46\", \"projectId\": 17, \"sortOrder\": 0, \"updatedAt\": \"2026-09-15T21:24:46\", \"choiceText\": \"独自前往船尾寻找真相\", \"sourceNodeId\": 75, \"targetNodeId\": 76}, {\"id\": 65, \"enabled\": true, \"createdAt\": \"2026-09-15T21:26:20\", \"projectId\": 17, \"sortOrder\": 0, \"updatedAt\": \"2026-09-15T21:26:20\", \"choiceText\": \"寻找被隐藏的航线记录\", \"sourceNodeId\": 77, \"targetNodeId\": 78}, {\"id\": 66, \"enabled\": true, \"createdAt\": \"2026-09-15T21:26:55\", \"projectId\": 17, \"sortOrder\": 0, \"updatedAt\": \"2026-09-15T21:26:55\", \"choiceText\": \"不等罗吉说明，独自前往交易地点\", \"sourceNodeId\": 78, \"targetNodeId\": 79}, {\"id\": 68, \"enabled\": true, \"createdAt\": \"2026-09-15T21:29:50\", \"projectId\": 17, \"sortOrder\": 0, \"updatedAt\": \"2026-09-15T21:29:50\", \"choiceText\": \"接受罗吉的请求，共同提交证据\", \"sourceNodeId\": 80, \"targetNodeId\": 81}, {\"id\": 69, \"enabled\": true, \"createdAt\": \"2026-09-15T21:30:39\", \"projectId\": 17, \"sortOrder\": 0, \"updatedAt\": \"2026-09-15T21:30:39\", \"choiceText\": \"将答案留给未来的重逢\", \"sourceNodeId\": 81, \"targetNodeId\": 82}, {\"id\": 72, \"enabled\": true, \"createdAt\": \"2026-09-15T21:41:39\", \"projectId\": 17, \"sortOrder\": 0, \"updatedAt\": \"2026-09-15T21:41:39\", \"choiceText\": \"相信希尔法的线索，调查海盗据点\", \"sourceNodeId\": 84, \"targetNodeId\": 85}, {\"id\": 73, \"enabled\": true, \"createdAt\": \"2026-09-15T21:42:30\", \"projectId\": 17, \"sortOrder\": 0, \"updatedAt\": \"2026-09-15T21:42:30\", \"choiceText\": \"放弃追查，离开海洋开始平静生活\", \"sourceNodeId\": 85, \"targetNodeId\": 86}, {\"id\": 75, \"enabled\": true, \"createdAt\": \"2026-09-15T21:43:23\", \"projectId\": 17, \"sortOrder\": 0, \"updatedAt\": \"2026-09-15T21:43:23\", \"cho