: \"毁灭风险\", \"variableKey\": \"danger_level\", \"initialValue\": \"0\"}, {\"id\": 18, \"projectId\": 17, \"valueType\": \"INTEGER\", \"description\": \"用于区分吉奥多线的普通结局与圆满结局\", \"displayName\": \"吉奥多好感度\", \"variableKey\": \"geordo_affection\", \"initialValue\": \"0\"}, {\"id\": 19, \"projectId\": 17, \"valueType\": \"INTEGER\", \"description\": \"用于区分吉斯线的普通结局与圆满结局。\", \"displayName\": \"吉斯好感度\", \"variableKey\": \"keith_affection\", \"initialValue\": \"0\"}, {\"id\": 20, \"projectId\": 17, \"valueType\": \"BOOLEAN\", \"description\": \"标记是否取得能揭露船上异常的关键证据。\", \"displayName\": \"吉斯关键证据\", \"variableKey\": \"keith_evidence\", \"initialValue\": \"false\"}, {\"id\": 21, \"projectId\": 17, \"valueType\": \"INTEGER\", \"description\": \"用于区分亚兰线的普通结局与圆满结局。\", \"displayName\": \"亚兰好感度\", \"variableKey\": \"alan_affection\", \"initialValue\": \"0\"}, {\"id\": 22, \"projectId\": 17, \"valueType\": \"BOOLEAN\", \"description\": \"标记是否取得白雾事件背后的关键证据。\", \"displayName\": \"亚兰关键证据\", \"variableKey\": \"alan_evidence\", \"initialValue\": \"false\"}, {\"id\": 23, \"projectId\": 17, \"valueType\": \"INTEGER\", \"description\": \"用于区分尼克尔线的普通结局与圆满结局。\", \"displayName\": \"尼克尔好感度\", \"variableKey\": \"nicol_affection\", \"initialValue\": \"0\"}, {\"id\": 24, \"projectId\": 17, \"valueType\": \"BOOLEAN\", \"description\": \"标记是否取得与白雾和宝石有关的关键证据。\", \"displayName\": \"尼克尔关键证据\", \"variableKey\": \"nicol_evidence\", \"initialValue\": \"false\"}, {\"id\": 25, \"projectId\": 17, \"valueType\": \"INTEGER\", \"description\": \"用于区分罗吉线的普通结局与圆满结局。\", \"displayName\": \"罗吉好感度\", \"variableKey\": \"rogi_affection\", \"initialValue\": \"0\"}, {\"id\": 26, \"projectId\": 17, \"valueType\": \"BOOLEAN\", \"description\": \"标记是否取得揭露罗吉真实立场的关键证据。\", \"displayName\": \"罗吉关键证据\", \"variableKey\": \"rogi_evidence\", \"initialValue\": \"false\"}, {\"id\": 27, \"projectId\": 17, \"valueType\": \"BOOLEAN\", \"description\": \"吉奥多、吉斯、亚兰、尼克尔任意一条路线达成通关结局后解锁罗吉线与希尔法线。\", \"displayName\": \"隐藏路线已解锁\", \"variableKey\": \"hidden_routes_unlocked\", \"initialValue\": \"false\"}, {\"id\": 28, \"projectId\": 17, \"valueType\": \"INTEGER\", \"description\": \"用于区分希尔法线的普通结局与圆满结局。\", \"displayName\": \"希尔法好感度\", \"variableKey\": \"silva_affection\", \"initialValue\": \"0\"}, {\"id\": 29, \"projectId\": 17, \"valueType\": \"BOOLEAN\", \"description\": \"标记是否取得揭露希尔法过去与阴谋的关键证据。\", \"displayName\": \"希尔法关键证据\", \"variableKey\": \"silva_evidence\", \"initialValue\": \"false\"}], \"characters\": [{\"id\": 1, \"goal\": \"平安结束航行，并守护重要的人。\", \"name\": \"卡塔莉娜·库莱耶思\", \"status\": \"ACTIVE\", \"summary\": \"本作主人公，受邀登上维克尔姆号参加首次航行。\", \"createdAt\": \"2026-09-14T22:21:51\", \"projectId\": 17, \"updatedAt\": \"2026-09-14T22:21:51\", \"valueOrder\": \"同伴 > 自由 > 美食 > 安全\", \"personality\": \"单纯直率，喜爱美食，对危险常后知后觉。\"}, {\"id\": 2, \"goal\": \"保护卡塔莉娜，并让她优先选择自己。\", \"name\": \"吉奥尔多·史提亚德\", \"status\": \"ACTIVE\", \"summary\": \"金发碧眼的王子，卡塔莉娜的未婚夫。\", \"createdAt\": \"2026-09-14T22:25:35\", \"projectId\": 17, \"updatedAt\": \"2026-09-14T22:25:35\", \"valueOrder\": \"卡塔莉娜 > 王室责任 > 同伴 > 体面\", \"personality\": \"表面优雅，实际腹黑、占有欲强，行动果断.\"}, {\"id\": 3, \"goal\": \"守护卡塔莉娜，证明自己值得被家人信赖。\", \"name\": \"吉斯·库莱耶思\", \"status\": \"ACTIVE\", \"summary\": \"因魔力高强而被库莱耶思家收养的义弟.\", \"createdAt\": \"2026-09-14T22:26:13\", \"projectId\": 17, \"updatedAt\": \"2026-09-14T22:26:13\", \"valueOrder\": \"卡塔莉娜 > 家人 > 责任 > 自我\", \"personality\": \"温柔细致，责任心强，容易将担忧压在心里。\"}, {\"id\": 4, \"goal\": \"摆脱“王子弟弟”的比较，坦率面对自己的心意。\", \"name\": \"亚兰·史提亚德\", \"status\": \"ACTIVE\", \"summary\": \"吉奥尔多的双胞胎弟弟，拥有出众的音乐才能。\", \"createdAt\": \"2026-09-14T22:26:51\", \"projectId\": 17, \"updatedAt\": \"2026-09-14T22:26:51\", \"valueOrder\": \"自我价值 > 卡塔莉娜 > 音乐 > 王室责任\", \"personality\": \"嘴硬直接，自尊心强，情感表达笨拙。\"}, {\"id\": 5, \"goal\": \"守护妹妹与重要的人，并寻找真正想要的未来。\", \"name\": \"尼克尔·阿斯喀特\", \"status\": \"ACTIVE\", \"summary\": \"宰相之子，外貌精致，也很疼爱妹妹索菲亚。\", \"createdAt\": \"2026-09-14T22:27:27\", \"projectId\": 17, \"updatedAt\": \"2026-09-14T22:27:27\", \"valueOrder\": \"家人 > 卡塔莉娜 > 责任 > 名望\", \"personality\": \"沉稳克制，温和细腻，不轻易表露情绪\"}, {\"id\": 6, \"goal\": \"查清航行中的异常，并保护自己认可的人。\", \"name\": \"罗吉·林德\", \"status\": \"ACTIVE\", \"summary\": \"参与维克尔姆号下水典礼与首次航行的外国维修人员。\", \"createdAt\": \"2026-09-14T22:28:12\", \"projectId\": 17, \"updatedAt\": \"2026-09-14T22:28:12\", \"valueOrder\": \"真相 > 同伴 > 自由 > 自我救赎\", \"personality\": \"亲切温和，擅长照顾人，隐藏着不愿轻易说出的过去\"}, {\"id\": 7, \"goal\": \"处理与海盗团及过去有关的危机，决定自己的未来。\", \"name\": \"希尔法\", \"status\": \"ACTIVE\", \"summary\": \"出没于白雾海域的白闇海盗团青年船长。\", \"createdAt\": \"2026-09-14T22:28:52\", \"projectId\": 17, \"updatedAt\": \"2026-09-14T22:28:52\", \"valueOrder\": \"自由 > 船员 > 卡塔莉娜 > 过去\", \"personality\": \"神秘强势，言行带有压迫感，却有自己的原则。\"}, {\"id\": 8, \"goal\": \"留在卡塔莉娜身边，守护两人的关系。\", \"name\": \"玛丽·亨特\", \"status\": \"ACTIVE\", \"summary\": \"侯爵千金，与卡塔莉娜相识后逐渐成长为社交界闻名的淑女。\", \"createdAt\": \"2026-09-15T13:56:45\", \"projectId\": 17, \"updatedAt\": \"2026-09-15T13:56:45\", \"valueOrder\": \"卡塔莉娜 > 自由 > 家族期待 > 社交声望\", \"personality\": \"表面端庄温柔，内心坚定，对重要的人有很强执着。\"}, {\"id\": 9, \"goal\": \"接纳真实的自己，与哥哥和朋友共同前进。\", \"name\": \"索菲亚·阿斯喀特\", \"status\": \"ACTIVE\", \"summary\": \"尼克尔的妹妹，喜爱阅读，与卡塔莉娜因同读恋爱小说而成为好友。\", \"createdAt\": \"2026-09-15T13:57:58\", \"projectId\": 17, \"updatedAt\": \"2026-09-15T13:57:58\", \"valueOrder\": \"家人 > 友情 > 阅读 > 自我成长\", \"personality\": \"腼腆敏感，温柔善良，面对熟人会表现出热情。\"}, {\"id\": 10, \"goal\": \"以自己的能力帮助身边的人，走向想要的未来。\", \"name\": \"玛丽亚·坎贝尔\", \"status\": \"ACTIVE\", \"summary\": \"原本乙女游戏《FORTUNE LOVER》的主人公，擅长制作点心。\", \"createdAt\": \"2026-09-15T13:58:47\", \"projectId\": 17, \"updatedAt\": \"2026-09-15T13:58:47\", \"valueOrder\": \"同伴 > 努力 > 善意 > 自我实现\", \"personality\": \"勤奋温和，乐于帮助他人，心意坚定。\"}], \"conditions\": [{\"id\": 35, \"choiceId\": 33, \"operator\": \"GTE\", \"sortOrder\": 0, \"variableId\": 15, \"expectedValue\": \"2\", \"conditionGroup\": 0}, {\"id\": 17, \"choiceId\": 41, \"operator\": \"GTE\", \"sortOrder\": 0, \"variableId\": 17, \"expectedValue\": \"1\", \"conditionGroup\": 0}, {\"id\": 41, \"cho