INSERT INTO `test_feedback` VALUES (10, 17, 14, 3, '复杂路线 HAPPY 结局验收通过', '已完成复杂剧情图前端验收。结构检测结果为 0 错误、0 警告；HAPPY 路径按预期满足关键线索数 2、路线推进度 2、吉奥多好感度 2、密图已获得 true，并正确进入圆满结局。', 'RESOLVED', '2026-09-14 21:53:43', '2026-09-14 21:53:55', NULL);
INSERT INTO `test_feedback` VALUES (11, 17, 17, 3, '冻结版本显示编号与会话编号不一致', '在模拟测试中选择“冻结版本 v2”后启动会话，页面右上角仍显示“冻结版本 v2”，但会话详情和左侧会话卡片显示“版本 #3”。建议统一版本显示编号，或同时展示版本名称与内部编号，避免测试人员误判运行的剧情快照。', 'OPEN', '2026-09-14 22:00:03', '2026-09-14 22:00:03', NULL);
INSERT INTO `test_feedback` VALUES (12, 17, 31, 3, '隐藏路线解锁状态不会跨模拟保留', '完成尼克尔线 HAPPY ENDING 后，hidden_routes_unlocked 在当前会话中已变为 true；但重新开始模拟后会恢复为 false，导致需要累计通关才能解锁的罗吉线和希尔法法线无法继续出现。建议将隐藏路线解锁进度改为跨会话持久化数据。', 'OPEN', '2026-09-16 21:31:10', '2026-09-16 21:31:10', NULL);
INSERT INTO `test_feedback` VALUES (13, 17, 34, 19, '权限测试反馈', '用于验证 TESTER 可以提交反馈，但不能处理反馈。', 'RESOLVED', '2026-09-24 20:09:57', '2026-09-24 20:12:09', 118);
INSERT INTO `world_entry` VALUES (2, 17, 'SETTING', '索西亚王国、邻国与航海舞台', '故事以拥有魔法与贵族制度的索西亚王国为基础舞台。魔力被视为与生俱来的资质，王室与贵族家系共同维系国家秩序；魔法学园则承担贵族子弟的知识、礼仪与魔法教育。\n\n本次“掀起波澜的海盗”航线将舞台延伸至邻国及两国之间的海域。卡塔莉娜一行乘坐维克尔姆号出航，在异国港口、海上航路与当地势力之间遭遇白雾、宝石和海盗相关的异常事件。邻国的社会风俗、权力关系与索西亚王国并不完全相同，因此也成为各条个人路线发生冲突、合作与感情推进的重要背景。', 0, '2026-09-15 22:29:15', '2026-09-15 22:29:15');
INSERT INTO `world_entry` VALUES (3, 17, 'LOCATION', '邻国港口与维克尔姆号', '维克尔姆号是卡塔莉娜一行在本次航线中乘坐的船只，也是事件调查与角色互动的主要场景。船上设有客舱、甲板、资料室、储藏室等区域；白雾出现后，船内外不断发生异常，船员与乘客之间的猜疑也随之扩大。\n\n邻国港口是航行补给、情报交换与调查展开的关键地点。来自不同国家的商人、贵族与航海者在此往来，使港口同时具备公开的繁荣景象与暗处的交易网络。白雾、宝石与海盗活动的线索会在港口和维克尔姆号之间交错出现。', 10, '2026-09-15 22:30:49', '2026-09-15 22:30:49');
INSERT INTO `world_entry` VALUES (4, 17, 'RULE', '白雾与宝石的异常规则', '航线中的白雾并非普通气候现象。它会遮蔽视野、扰乱方向感，并放大船员与乘客心中的不安；越接近异常源头，迷失、误判和失散的风险越高。\n\n与白雾相关的宝石具有特殊力量。宝石会对持有者的情绪、愿望或使用方式产生反应：处理得当时可以成为驱散危机的线索，处理失当时则可能引发更严重的失控。各路线围绕宝石取得、证据收集、是否独自行动与是否信任同伴，形成不同分歧和结局。', 20, '2026-09-15 22:33:20', '2026-09-15 22:33:20');
INSERT INTO `world_entry` VALUES (5, 17, 'FACTION', '海盗势力与港口情报网', '邻国港口表面上由商会、贵族与港务人员共同维持秩序，暗中却存在以走私、情报买卖和稀有物资交易为生的网络。海盗并非单一阵营：有人只为利益行动，也有人掌握航线、遗迹或宝石来源的关键情报。\n\n维克尔姆号上的调查会不可避免地触及这些势力。主角一行需要分辨哪些消息可信、哪些交易暗藏陷阱，并在保护船员安全、维持两国关系和追查真相之间作出选择。不同角色对海盗与邻国势力的判断不同，这会影响合作关系与路线走向。', 30, '2026-09-15 22:36:12', '2026-09-15 22:36:12');
INSERT INTO `world_entry` VALUES (6, 17, 'HISTORY', '白雾航线事件的开端', '维克尔姆号驶向邻国期间，海面突然出现覆盖航路的白雾。起初，船员将其视为普通的海上异象；随后船灯熄灭、航向异常、乘客间流言扩散，证明这并非偶发事故。\n\n调查逐渐指向一颗曾在航海记录与港口交易中反复出现的宝石。宝石的流转牵连邻国港口、海盗势力与船上乘客，各方都掌握部分线索，也都可能隐瞒真实目的。卡塔莉娜一行必须在抵达邻国前厘清真相，避免白雾将整艘船与两国关系一同卷入失控的危机。', 40, '2026-09-15 22:37:59', '2026-09-15 22:37:59');
